"use client";

/**
 * File attach: file thumbnails slide in from the side, drop into a prompt
 * composer and shrink into attachment chips. The prompt then types itself and
 * the send button presses. The "give it your context" beat of an AI product film.
 *
 * Written by Better Design. Painted from the theme prop.
 */
import { loadFont } from "@remotion/google-fonts/Inter";
import { AbsoluteFill, Img, interpolate, useCurrentFrame } from "remotion";
import { easings, pickFont, type VideoTheme, useVideoTheme, withAlpha } from "@/lib/bd-video";

const { fontFamily: INTER } = loadFont("normal", { weights: ["400", "500", "600", "700"], subsets: ["latin"] });

const W = 1920;
const BOX = { left: 340, top: 430, width: 1240, pad: 32 };
const CHIP = { width: 300, height: 76, gap: 16 };
const THUMB = { width: 220, height: 270, gap: 44, top: 80 };
const STAGGER = 10;
const SLIDE = 22;
const DROP_AT = 30;
const DROP = 18;
const CHARS_PER_FRAME = 1.6;

export interface FileAttachProps {
  /** File names. The extension picks the drawing. Three or four fit. */
  files?: string[];
  /** Optional pictures, by index, shown on the thumbnails. Drawn placeholders stand in when absent. */
  thumbnails?: string[];
  /** The prompt that types itself once the files land. */
  prompt?: string;
  /** Grey text in the empty field. */
  placeholder?: string;
  theme?: Partial<VideoTheme>;
  /** A CSS font family the project has loaded. Defaults to the theme's face, then Inter. */
  font?: string;
}

const clamp = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;
const ext = (name: string): string => (name.includes(".") ? (name.split(".").pop() ?? "") : "file").toUpperCase();
const isImage = (name: string): boolean => /\.(png|jpe?g|gif|webp|svg|heic)$/i.test(name);

/** Files fly into a prompt composer as chips, then the prompt types and sends. */
export function FileAttach({
  files = ["brief.pdf", "moodboard.png", "notes.docx"],
  thumbnails = [],
  prompt = "Turn these into a one-page launch brief with three headline options.",
  placeholder = "Ask anything",
  theme: themeOverride,
  font,
}: FileAttachProps) {
  const theme = useVideoTheme(themeOverride);
  const frame = useCurrentFrame();
  const family = pickFont(font, theme, INTER);
  const list = files.slice(0, 4);
  const n = list.length;

  const landed = (n - 1) * STAGGER + DROP_AT + DROP;
  const typeAt = landed + 6;
  const typed = Math.floor(Math.max(0, frame - typeAt) * CHARS_PER_FRAME);
  const text = prompt.slice(0, typed);
  const pressAt = typeAt + Math.ceil(prompt.length / CHARS_PER_FRAME) + 6;
  const press = interpolate(frame, [pressAt, pressAt + 4, pressAt + 12], [0, 1, 0], clamp);
  const sent = easings.out(interpolate(frame, [pressAt + 2, pressAt + 14], [0, 1], clamp));
  const boxT = easings.out(interpolate(frame, [0, 16], [0, 1], clamp));
  const caretOn = frame < pressAt && (typed < prompt.length || Math.floor(frame / 8) % 2 === 0);

  // Once the chips land, the composer rises to the centre of the frame.
  const lift = easings.inOut(interpolate(frame, [landed, landed + 22], [0, 1], clamp)) * 72;
  const thumbsWidth = n * THUMB.width + (n - 1) * THUMB.gap;
  const radius = theme.radius * 2;

  return (
    <AbsoluteFill style={{ background: theme.background, fontFamily: family }}>
      <AbsoluteFill style={{ transform: `translateY(${-lift}px)` }}>
      <div
        style={{
          position: "absolute", left: BOX.left, top: BOX.top, width: BOX.width, padding: BOX.pad, borderRadius: radius * 1.4,
          background: theme.card, border: `1px solid ${theme.border}`, boxShadow: `0 30px 70px oklch(0 0 0 / 0.1)`,
          display: "flex", flexDirection: "column", gap: 24, opacity: boxT, transform: `translateY(${(1 - boxT) * 30}px)`,
        }}
      >
        <div style={{ height: CHIP.height }} />
        <div style={{ minHeight: 112, fontSize: 40, lineHeight: 1.4, fontWeight: 500, color: text ? theme.foreground : theme.mutedForeground }}>
          {text || (frame < typeAt ? placeholder : "")}
          {frame >= typeAt && <span style={{ display: "inline-block", width: 3, height: 44, marginLeft: 4, verticalAlign: "-8px", background: theme.primary, opacity: caretOn ? 1 : 0 }} />}
        </div>
        <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between" }}>
          <div style={{ width: 56, height: 56, borderRadius: 28, border: `1px solid ${theme.border}`, color: theme.mutedForeground, display: "flex", alignItems: "center", justifyContent: "center", fontSize: 34, fontWeight: 400 }}>+</div>
          <div
            style={{
              width: 72, height: 72, borderRadius: 36, display: "flex", alignItems: "center", justifyContent: "center",
              background: typed > 0 ? theme.primary : theme.muted, transform: `scale(${1 - press * 0.12})`,
              boxShadow: `0 0 0 ${sent * 22}px ${withAlpha(theme.primary, 0.25 * (1 - sent))}`,
            }}
          >
            <svg width={32} height={32} viewBox="0 0 24 24">
              <path d="M12 19 V5 M5.5 11.5 L12 5 L18.5 11.5" fill="none" stroke={typed > 0 ? theme.primaryForeground : theme.mutedForeground} strokeWidth={2.6} strokeLinecap="round" strokeLinejoin="round" />
            </svg>
          </div>
        </div>
      </div>

      {list.map((name, i) => {
        const s = i * STAGGER;
        const a = easings.out(interpolate(frame, [s, s + SLIDE], [0, 1], clamp));
        const b = easings.inOut(interpolate(frame, [s + DROP_AT, s + DROP_AT + DROP], [0, 1], clamp));
        const hoverX = (W - thumbsWidth) / 2 + i * (THUMB.width + THUMB.gap);
        const chipX = BOX.left + BOX.pad + i * (CHIP.width + CHIP.gap);
        const x = interpolate(b, [0, 1], [interpolate(a, [0, 1], [-THUMB.width - 80 - i * 60, hoverX]), chipX]);
        const y = interpolate(b, [0, 1], [THUMB.top, BOX.top + BOX.pad]);
        const w = interpolate(b, [0, 1], [THUMB.width, CHIP.width]);
        const h = interpolate(b, [0, 1], [THUMB.height, CHIP.height]);
        const thumbO = 1 - Math.min(b * 2, 1);
        const chipO = Math.max(b * 2 - 1, 0);
        const tilt = (1 - a) * -8 + Math.sin(b * Math.PI) * 3;
        const picture = thumbnails[i];
        return (
          <div
            key={i}
            style={{
              position: "absolute", left: x, top: y, width: w, height: h, borderRadius: interpolate(b, [0, 1], [radius * 1.2, radius]),
              background: b < 0.5 ? theme.card : theme.muted, border: `1px solid ${theme.border}`, overflow: "hidden",
              boxShadow: `0 ${20 * (1 - b)}px ${40 * (1 - b)}px oklch(0 0 0 / 0.12)`, transform: `rotate(${tilt}deg)`,
            }}
          >
            <div style={{ position: "absolute", inset: 14, display: "flex", flexDirection: "column", gap: 12, opacity: thumbO }}>
              <div style={{ position: "relative", flex: 1, borderRadius: radius * 0.6, background: withAlpha(theme.primary, 0.1), overflow: "hidden" }}>
                {picture ? (
                  <Img src={picture} style={{ width: "100%", height: "100%", objectFit: "cover" }} />
                ) : isImage(name) ? (
                  <svg width="100%" height="100%" viewBox="0 0 100 100" preserveAspectRatio="none">
                    <circle cx={72} cy={30} r={11} fill={withAlpha(theme.primary, 0.55)} />
                    <path d="M0 100 L0 74 L30 46 L56 72 L72 58 L100 82 L100 100 Z" fill={withAlpha(theme.primary, 0.4)} />
                  </svg>
                ) : (
                  <div style={{ position: "absolute", inset: 18, display: "flex", flexDirection: "column", gap: 11 }}>
                    {[1, 0.85, 0.95, 0.6, 0.9, 0.7].map((f, k) => (
                      <div key={k} style={{ height: 9, width: `${f * 100}%`, borderRadius: 5, background: withAlpha(theme.primary, k === 0 ? 0.5 : 0.25) }} />
                    ))}
                  </div>
                )}
              </div>
              <div style={{ fontSize: 22, fontWeight: 600, color: theme.foreground, whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>{name}</div>
            </div>
            <div style={{ position: "absolute", inset: 0, display: "flex", alignItems: "center", gap: 16, padding: "0 18px", opacity: chipO }}>
              <div style={{ flexShrink: 0, width: 48, height: 48, borderRadius: theme.radius, background: theme.primary, color: theme.primaryForeground, display: "flex", alignItems: "center", justifyContent: "center", fontSize: 14, fontWeight: 700 }}>
                {ext(name).slice(0, 4)}
              </div>
              <div style={{ fontSize: 24, fontWeight: 600, color: theme.foreground, whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>{name}</div>
            </div>
          </div>
        );
      })}
      </AbsoluteFill>
    </AbsoluteFill>
  );
}
